<template>
  <div>
    <div class="event-popup">

      <div class="tit">是否删除该{{ makerTitle }}点？</div>
      <div class="info">纬度:{{ lat }}</div>
      <div class="info">经度:{{ lan }}</div>
      <div class="btn_div">
        <div class="btn" @click="clickBtn(true)">确定</div>
        <div class="btn" @click="clickBtn(false)">取消</div>
      </div>
    </div>
  </div>
</template>
<script>
export default {
  props:['makerTitle','eventMakerInfo'],
  data() {
    return {
      lat: 0,
      lan: 0
    }

  },
  watch: {
    eventMakerInfo(val){
      //console.log("eventMakerInfo");
      //console.log(val.getExtData());

      this.lat=val.getExtData().latitude;
      this.lan=val.getExtData().longitude;
    }
  },
  methods:{
    clickBtn(val){
      this.$emit("selectMakerBtn",val)
    }
  }
}
</script>
<style lang="scss" scoped src="../assets/css/eventMakerPopup.scss"></style>